class Solution {
  public int[] largestSubarray(int[] nums, int k) {
    // elements are distinct, so the largest subarray starts at the largest possible first element
    int best = 0;
    for (int i = 1; i + k <= nums.length; i++) if (nums[i] > nums[best]) best = i;
    return java.util.Arrays.copyOfRange(nums, best, best + k);
  }
}
